      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit QED made strong, controllable light--matter interaction in superconducting circuits a foundational experimental platform.",
        "attribution": "Blais supplied a decisive theoretical framework, while Wallraff and Schoelkopf established the defining experimental realization.",
        "maturity": "The phenomena are reproducible across laboratories and underpin a major branch of quantum physics.",
        "uncertainties": [
          "The contribution overlaps historically with the broader superconducting-circuit advances recognized in 2025."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B007",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction established the physical-information principle required for scalable quantum computation.",
        "attribution": "Shor's code, Steane's codes and fault-tolerance concepts, and Kitaev's foundational formulations are distinct seminal contributions.",
        "maturity": "The theory is exceptionally mature and increasingly supported by experimental logical-qubit demonstrations.",
        "uncertainties": [
          "Full fault-tolerant computation has not yet been achieved."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B003",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller",
        "Rainer Blatt"
      ],
      "assessment": {
        "nobel_worthiness": "Trapped ions provided one of the cleanest controlled quantum systems for computation, simulation, and precision tests.",
        "attribution": "Cirac and Zoller formulated pivotal schemes; Blatt led landmark experimental realization and scaling.",
        "maturity": "Decades of independent, high-fidelity experiments establish the platform's robustness.",
        "uncertainties": [
          "The boundary between credit for trapped-ion computing and the broader atomic quantum-information field needs careful definition."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B043",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks transformed precision timekeeping and enabled exquisitely sensitive tests of fundamental physics.",
        "attribution": "Katori introduced the magic-wavelength lattice-clock concept and Ye made defining experimental advances.",
        "maturity": "Performance and reproducibility are established internationally, with broad scientific consequences.",
        "uncertainties": [
          "The relative credit due to other metrology pioneers would require detailed historical review."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Andrew N. Cleland",
        "John D. Teufel",
        "Markus Aspelmeyer"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum optomechanics brought engineered mechanical objects into the quantum regime and made their motion controllable at the quantum limit.",
        "attribution": "Cleland and Teufel achieved landmark microwave-mechanical quantum control; Aspelmeyer was central to the field's optical development.",
        "maturity": "Ground-state cooling, quantum control, and transduction experiments are well established.",
        "uncertainties": [
          "Credit is distributed across several optical and microwave approaches, making a three-person selection difficult."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B040",
      "proposed_laureates": [
        "Artur Ekert",
        "Charles H. Bennett",
        "Gilles Brassard"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum cryptography revealed an operationally powerful consequence of quantum measurement and entanglement.",
        "attribution": "Bennett and Brassard originated seminal protocols, while Ekert supplied the entanglement-based formulation.",
        "maturity": "The principles have been repeatedly validated and now support extensive field demonstrations.",
        "uncertainties": [
          "The appropriate balance between foundational protocol inventors and later network builders is contestable."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B014",
      "proposed_laureates": [
        "Eli Yablonovitch",
        "John D. Joannopoulos",
        "Sajeev John"
      ],
      "assessment": {
        "nobel_worthiness": "Photonic crystals created a new way to control electromagnetic modes and spontaneous emission through structured media.",
        "attribution": "John and Yablonovitch introduced decisive concepts, with Joannopoulos providing foundational theoretical development.",
        "maturity": "The field has produced durable physics and many experimentally realized structures.",
        "uncertainties": [
          "Its broad technological impact does not by itself settle whether the core discovery is prize-sized."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B029",
      "proposed_laureates": [
        "David DeMille",
        "John M. Doyle",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Ultracold molecules opened controlled access to strongly dipolar quantum matter, chemistry, and precision measurement.",
        "attribution": "DeMille, Doyle, and Ye made complementary foundational advances in production, control, and use of cold molecular systems.",
        "maturity": "The field is experimentally mature and expanding rapidly across several platforms.",
        "uncertainties": [
          "The discovery encompasses multiple routes and may not yet have a sufficiently singular attribution."
        ]
      }
    }
  ]
